import { test, expect } from '@playwright/test';

test.describe('Full-screen modals on small viewports', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-website-url.com');
    await page.setViewportSize({ width: 375, height: 667 }); // Simulate small viewport
  });

  test('should display modal in full-screen on small viewport', async ({ page }) => {
    await page.getByText('Open Modal').click();
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();
    await expect(modal).toHaveCSS('width', '100%');
    await expect(modal).toHaveCSS('height', '100%');
  });

  test('should close the modal when the close button is clicked', async ({ page }) => {
    await page.getByText('Open Modal').click();
    const closeButton = page.getByLabel('Close');
    await closeButton.click();
    const modal = page.getByRole('dialog');
    await expect(modal).not.toBeVisible();
  });
});
